def inside(pt, poly):
    x,y=pt # r,v
    ins=False
    for (x1,y1),(x2,y2) in zip(poly, poly[1:]+poly[:1]):
        if (y1>y)!=(y2>y):
            xin=x1+(y-y1)*(x2-x1)/(y2-y1)
            if x<xin: ins=not ins
    return ins
